// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Vietnamese what-why-fix messages for every typed error
// Flo: error value > Vietnamese three-line message
// I/O: anyerror (caller) > Mesg (what, why, fix)
// ===================================================================
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn mesg(erro: anyerror) Mesg { return switch (erro) { error.NeedForce => .{ .what = "cần xác nhận thêm", .whyz = "việc này (nhóm, chuyển tiếp, xóa, người lạ) phải được duyệt trước", .fixz = "xem bản xem trước rồi chạy lại với --live --force" }, error.BadUsage => .{ .what = "dùng sai lệnh", .whyz = "lệnh hoặc cờ không đúng", .fixz = "chạy: za help" }, error.BadJob => .{ .what = "việc không hợp lệ", .whyz = "tên việc sai hoặc thiếu thông tin", .fixz = "chạy: za help" }, error.BadConfig => .{ .what = "cấu hình sai", .whyz = "aa-conf-main.json có giá trị không hợp lệ", .fixz = "sửa giá trị đó hoặc xóa tệp để dùng mặc định" }, error.Halted => .{ .what = "đã dừng", .whyz = "Zalo hiện captcha, khóa, cảnh báo hoặc đăng nhập nơi khác", .fixz = "mở Zalo, xử lý xong rồi chạy: za resume" }, error.CapHit => .{ .what = "hết hạn mức", .whyz = "đã dùng hết số lượt gửi của giờ hoặc ngày", .fixz = "chờ hết giờ hoặc ngày; đừng tăng hạn mức quá nhanh" }, error.QuietHrs => .{ .what = "đang giờ nghỉ", .whyz = "hiện nằm trong khoảng quie_hour_rang", .fixz = "chạy lại sau hoặc đổi quie_hour_rang" }, error.NoElem => .{ .what = "không thấy nút hoặc ô", .whyz = "tên trên trang Zalo đã đổi hoặc chưa tải xong", .fixz = "chạy: za run canary --read rồi sửa tên trong so-labl-zalo.json" }, error.NeedLogin => .{ .what = "cần đăng nhập", .whyz = "Zalo Web đang hiện mã QR", .fixz = "chạy: za login rồi quét mã QR bằng Zalo trên điện thoại" }, error.NoBrowser => .{ .what = "không có trình duyệt", .whyz = "không tìm thấy Chrome hoặc Edge", .fixz = "cài Chrome hoặc đặt brow_exec_path" }, error.BrowFail => .{ .what = "trình duyệt lỗi", .whyz = "không mở được hoặc lệnh trang thất bại", .fixz = "đóng các cửa sổ za khác rồi thử lại" }, error.Timeout => .{ .what = "quá thời gian", .whyz = "không có phản hồi kịp lúc", .fixz = "thử lại sau" }, error.Closed => .{ .what = "mất kết nối trình duyệt", .whyz = "trình duyệt bị đóng giữa chừng", .fixz = "chạy lại; za tiếp tục từ chỗ dở và không gửi trùng" }, error.BadHandshake => .{ .what = "không kết nối được", .whyz = "bắt tay với trình duyệt thất bại", .fixz = "đóng trình duyệt của za rồi thử lại" }, error.BadFrame => .{ .what = "dữ liệu trình duyệt lạ", .whyz = "gói tin không đọc được", .fixz = "thử lại; nếu lặp lại hãy cập nhật Chrome" }, error.CdpError => .{ .what = "trình duyệt từ chối lệnh", .whyz = "lệnh điều khiển trang bị lỗi", .fixz = "thử lại; nếu lặp lại chạy: za report" }, error.TooBig => .{ .what = "quá lớn", .whyz = "tệp hoặc dữ liệu vượt giới hạn", .fixz = "dùng tệp nhỏ hơn hoặc tăng file_size_maxz" }, error.LaunchTimeout => .{ .what = "trình duyệt khởi động chậm", .whyz = "không thấy cổng gỡ lỗi", .fixz = "đóng cửa sổ Chrome dùng hồ sơ của za rồi thử lại" }, error.NoPage => .{ .what = "không thấy trang", .whyz = "trình duyệt chưa mở trang nào", .fixz = "thử lại" }, error.DupSend => .{ .what = "gửi trùng", .whyz = "tin này đã gửi vào cuộc trò chuyện này", .fixz = "không cần làm gì" }, error.SqliOpen, error.SqliExec, error.SqliPrep, error.SqliBind, error.SqliStep => .{ .what = "lỗi cơ sở dữ liệu", .whyz = "không đọc hoặc ghi được tệp trạng thái", .fixz = "kiểm tra ổ đĩa còn chỗ; chạy: za backup rồi thử lại" }, error.AiFail => .{ .what = "AI không trả lời", .whyz = "công cụ AI không cho kết quả hợp lệ", .fixz = "tắt smar_mode_enab hoặc sửa lệnh AI" }, error.Ambiguous => .{ .what = "tên trùng", .whyz = "có nhiều cuộc trò chuyện cùng tên", .fixz = "thêm #group hoặc #person sau tên" }, error.Busy => .{ .what = "đang chạy", .whyz = "một lần chạy khác của za đang giữ khóa", .fixz = "chờ nó xong hoặc chạy: za status" }, error.UnknownModal => .{ .what = "cửa sổ lạ", .whyz = "có hộp thoại za chưa biết chặn trang", .fixz = "tự đóng nó rồi chạy lại" }, error.ChatFailed => .{ .what = "cuộc trò chuyện từ chối tin", .whyz = "một tin gửi vào đây đã thất bại trong 24 giờ qua", .fixz = "kiểm tra cuộc trò chuyện bằng tay (bị chặn hoặc bị xóa?)" }, error.NoConsent => .{ .what = "chưa đồng ý rủi ro", .whyz = "Zalo không cho phép tự động hóa; cần bạn đồng ý một lần", .fixz = "chạy: za setup --yes" }, error.Fail => .{ .what = "thất bại", .whyz = "việc không hoàn tất", .fixz = "xem: za log" }, else => .{ .what = "lỗi", .whyz = @errorName(erro), .fixz = "chạy lại với --json và xem: za status" } }; }
